/* Isolated, in-memory sandbox using the same combat and arrow interface as classrooms. */
(()=>{
'use strict';
const R=RegimentGame.forMode('battle-lab'),$=id=>document.getElementById(id),world=generateStudentWorld(218,GRIA_TEMPLATE);
let setup=R.create(world),state=null,mode='setup',active=0;setup.units=[];setup.nextId=1;
const sides=setup.countries.slice(0,4);let territory=setup.countries[0].capital;
const option=(select,value,text)=>{const o=document.createElement('option');o.value=value;o.textContent=text;select.append(o);};
sides.forEach(c=>option($('side'),c.id,c.name));setup.territories.forEach(t=>option($('field'),t.id,t.name+' · '+(t.biome?.name||'land')));$('field').value=territory;
Object.entries(R.types).forEach(([key,t])=>option($('type'),key,t.name));
function gear(){const old=$('gear').value;$('gear').replaceChildren();R.development.gearNames[$('type').value].forEach((name,i)=>option($('gear'),i,name));if([...$('gear').options].some(o=>o.value===old))$('gear').value=old;$('piece').querySelector('img').src='troop-icons/'+($('type').value==='cavalry'?'cavalry-cutout':$('type').value)+'.png';}
function report(message){$('status').textContent=message;}
function safely(fn){try{fn();}catch(e){report(e.message);}}
function add(){if(mode!=='setup')return;const n=Number($('count').value),hp=Number($('health').value);if(!Number.isInteger(n)||n<1||n>8||setup.units.filter(u=>u.country===active).length+n>8)throw Error('Use 1–8 troops per country in this demo.');if(!Number.isInteger(hp)||hp<1||hp>100)throw Error('Health must be 1–100.');for(let i=0;i<n;i++)setup.units.push({id:setup.nextId++,country:active,territory,type:$('type').value,hp,gear:Number($('gear').value),order:null,fatigue:0,retreat:null,retreatTo:null,readyTurn:setup.turn,supportTurn:0});R.validate(setup);render();report('Troops placed. Switch country to build the opposing side.');}
function prepare(){if(new Set(setup.units.map(u=>u.country)).size<2)throw Error('Place troops for at least two countries.');state=R.advance(setup);mode='orders';render();report('Drag from your bottom-row troop onto an opponent to attack. Switch country to command each side.');}
function render(){const s=mode==='setup'?setup:state,own=s.units.filter(u=>u.country===active&&u.hp>0);$('help').textContent=mode==='setup'?'Choose a country and troop, then drag its picture onto the battlefield or use Place troops. Each side can have up to eight regiments.':'Your country’s troops are along the bottom. Drag an attack arrow, or click a troop to choose Attack, Hold, or Retreat. Hold reduces incoming damage by 25%, or 40% for spears.';
for(const id of ['field','type','gear','health','count','piece','add','clear'])$(id).disabled=mode!=='setup';$('start').hidden=mode!=='setup';$('simulate').hidden=mode!=='orders';$('edit').hidden=mode==='setup';$('replay').hidden=mode!=='results';$('army').replaceChildren();if(mode==='setup')for(const u of own){const b=document.createElement('button');b.textContent=R.types[u.type].name+' #'+u.id+' · Remove';b.onclick=()=>{setup.units=setup.units.filter(t=>t.id!==u.id);render();};$('army').append(b);}
$('arena').replaceChildren();const countries=[...new Set(s.units.filter(u=>u.hp>0&&u.territory===territory).map(u=>u.country))];const e={territory,countries};{MovementView.decisions({host:$('arena'),s:{...s,phase:'decisions'},e,country:active,disabled:mode!=='orders',options:R.retreatOptions(s,own.find(u=>u.territory===territory)||{country:active,territory}),command:(unit,action,target)=>safely(()=>{R.battleOrder(state,active,unit,action,target);render();report('Order saved.');}),target:()=>{},retreat:()=>{}});} $('results').hidden=mode!=='results';}
function finishSides(){if(mode!=='orders')return;const remaining=[...new Set(state.conflicts.flatMap(e=>e.countries))].find(c=>!state.ready.includes(c));if(remaining!==undefined){active=remaining;$('side').value=active;render();MovementView.finishOrders({s:state,country:active,options:u=>R.retreatOptions(state,u),submit:orders=>safely(()=>{R.finishBattleOrders(state,active,orders);finishSides();})});return;}state=R.advance(state);mode='results';render();const host=$('results');host.replaceChildren();const h=document.createElement('h2');h.textContent='Battle results';host.append(h);const p=document.createElement('p');p.textContent='One simultaneous battle resolution. Edit the setup or try different orders to compare outcomes.';host.append(p);const table=document.createElement('table');table.innerHTML='<thead><tr><th>Country / troop</th><th>Starting health</th><th>Lost</th><th>Remaining</th></tr></thead>';const body=document.createElement('tbody');for(const battle of state.battles)for(const r of battle.records){const row=body.insertRow();for(const text of [state.countries[r.country].name+' · '+R.types[r.type].name+' #'+r.id,r.before,r.lost,r.remaining])row.insertCell().textContent=text;}table.append(body);host.append(table);if(!state.battles.length)p.textContent='All opposing troops withdrew. No battle was needed.';report('Simulation complete. See the results below.');host.scrollIntoView({behavior:'smooth',block:'start'});}
$('side').onchange=()=>{active=Number($('side').value);render();};$('field').onchange=()=>{territory=Number($('field').value);setup.units.forEach(u=>u.territory=territory);render();};$('type').onchange=gear;$('add').onclick=()=>safely(add);$('start').onclick=()=>safely(prepare);$('simulate').onclick=()=>safely(finishSides);$('edit').onclick=()=>{mode='setup';state=null;render();};$('replay').onclick=()=>safely(prepare);$('clear').onclick=()=>{setup.units=[];render();};
let drag=null,ghost=null;const piece=$('piece');function clearDrag(){ghost?.remove();ghost=null;drag=null;}piece.onpointerdown=e=>{if(mode!=='setup'||e.button!==0)return;piece.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY};ghost=piece.querySelector('img').cloneNode();ghost.className='demo-ghost';document.body.append(ghost);ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';e.preventDefault();};piece.onpointermove=e=>{if(drag?.id===e.pointerId){ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';}};piece.onpointerup=e=>{if(drag?.id!==e.pointerId)return;const b=$('arena').getBoundingClientRect(),inside=e.clientX>=b.left&&e.clientX<=b.right&&e.clientY>=b.top&&e.clientY<=b.bottom;clearDrag();if(inside)safely(add);else report('Drop onto the battlefield, or use Place troops.');};piece.onpointercancel=clearDrag;piece.onlostpointercapture=clearDrag;
gear();render();
})();
